def _backfill(connection):
    metadata = sa.MetaData()
    metadata.reflect(bind=connection)
    tables = metadata.tables

    def insert(name, row, **data):
        connection.execute(
            tables[name]
            .insert()
            .values(id=str(uuid4()), user_id=row["user_id"], created_at=row["created_at"], **data)
        )

    workspaces = {
        w["id"]: w for w in connection.execute(sa.select(tables["application_workspaces"])).mappings()
    }
    for w in workspaces.values():
        connection.execute(
            tables["opportunities"]
            .insert()
            .values(
                id=w["id"],
                user_id=w["user_id"],
                created_at=w["created_at"],
                workspace_id=w["id"],
                company=w["company"],
                role=w["role"],
                jd_raw=w["jd_raw"],
            )
        )
        for q in w["data"].get("questions", []):
            connection.execute(
                tables["application_questions"]
                .insert()
                .values(
                    id=q["id"],
                    user_id=w["user_id"],
                    created_at=w["created_at"],
                    workspace_id=w["id"],
                    text=q["text"],
                    character_limit=q["limit"],
                    state=w["data"].get("question_states", {}).get(q["id"], "CREATED"),
                )
            )
    for a in connection.execute(sa.select(tables["artifacts"])).mappings():
        common = {"workspace_id": a["workspace_id"], "artifact_id": a["id"]}
        data = a["data"]
        for kind, ids in [("ARTIFACT", a["depends_on"]), ("SOURCE", a["source_ids"])]:
            for ident in ids:
                insert("artifact_dependencies", a, **common, prerequisite_id=ident, prerequisite_type=kind)
        if a["kind"] == "OpportunityBrief":
            for output in data.get("actual_outputs", []):
                insert("opportunity_job_outputs", a, **common, output=output)
        elif a["kind"] == "EvidencePack":
            for item in data.get("items", []):
                insert(
                    "opportunity_evidence_maps",
                    a,
                    **common,
                    evidence_id=item["evidence_id"],
                    output=item["job_output_id"],
                    classification=item["classification"],
                    data=item,
                )
        elif a["kind"] in {"Draft", "ResumeContent"}:
            insert(
                "draft_versions",
                a,
                **common,
                question_id=a["slot"] or None,
                version=a["version"],
                content=data["text"],
                protected_spans=data.get("protected_spans", []),
            )
        elif a["kind"] == "CompanyResearchResult":
            insert("company_research_results", a, **common, data=data)
        elif a["kind"] in {"Review", "ResumeReview", "PortfolioReview"}:
            for issue in data.get("issues", []):
                insert("review_issues", a, **common, **{k: issue[k] for k in ["priority", "code", "message"]})
        elif a["kind"] == "SubmissionBundle":
            submitted = workspaces[a["workspace_id"]]["data"].get("submitted_at")
            insert(
                "submission_snapshots",
                a,
                **common,
                frozen_at=datetime.fromisoformat(data["frozen_at"]),
                submitted_at=datetime.fromisoformat(submitted) if submitted else None,
                content=data,
            )
        elif a["kind"] == "InterviewHandoff":
            insert(
                "interview_handoff_records",
                a,
                **common,
                submission_bundle_id=data["submission_bundle_id"],
                content=data,
            )
        elif a["kind"] == "Postmortem":
            insert(
                "postmortem_hypotheses",
                a,
                **common,
                observation=data["observation"],
                confidence=data["confidence"],
                attribution_scope=data["attribution_scope"],
            )
    for r in connection.execute(sa.select(tables["domain_records"])).mappings():
        data = r["data"]
        if r["kind"] == "SelectionOutcome" and data.get("workspace_id") in workspaces:
            connection.execute(
                tables["selection_outcomes"]
                .insert()
                .values(
                    id=r["id"],
                    user_id=r["user_id"],
                    created_at=r["created_at"],
                    workspace_id=data["workspace_id"],
                    stage=data["result"].split("_")[0],
                    result=data["result"],
                    notes=data.get("notes", ""),
                )
            )


